import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { gunzipSync } from 'node:zlib';
import { fileURLToPath } from 'node:url';
import { contained, assertComponents, readPinned, publishPinnedBytes } from './materializeHundredHandRuntimeAsset.mjs';

// Explicit source-validation tool only: Node plus existing Python 3 stdlib lzma.
// No install, network, postinstall, retail Python dependency, or model regeneration.
export const AUTHORING_INDEX_SHA256 = '32ed566b86b9486ce9ce85eff98ad059283446de09695976cb70bdeb978f8b6f';
const INDEX_PATH = 'scripts/assets/hundred-hand-mile/authoring/index.json';
const INDEX_BYTES = 26426;
const hash = value => createHash('sha256').update(value).digest('hex');
const bound = value => Number.isSafeInteger(value) && value > 0 && value <= 16 * 1024 * 1024;
function checkIdentity(spec) {
  if (!bound(spec.bytes) || !/^[a-f0-9]{64}$/.test(spec.sha256)) throw new Error('invalid bounded asset identity');
}
const PYTHON_XZ = [
  'import sys,lzma',
  'limit=int(sys.argv[1])',
  'd=lzma.LZMADecompressor(format=lzma.FORMAT_XZ,memlimit=67108864)',
  'b=d.decompress(sys.stdin.buffer.read(),max_length=limit+1)',
  'assert len(b)==limit and d.eof and not d.unused_data, "XZ length, EOF or trailing data mismatch"',
  'sys.stdout.buffer.write(b)'
].join(';');
export function decodePinnedAsset(stored, item) {
  checkIdentity(item); checkIdentity(item.storage);
  if (stored.length !== item.storage.bytes || hash(stored) !== item.storage.sha256)
    throw new Error('compressed asset identity mismatch');
  let raw;
  if (item.storage.encoding === 'gzip') raw = gunzipSync(stored, { maxOutputLength: item.bytes });
  else if (item.storage.encoding === 'xz') {
    try {
      raw = execFileSync('python3', ['-I', '-S', '-c', PYTHON_XZ, String(item.bytes)],
        { input: stored, maxBuffer: item.bytes + 1024, timeout: 30000, windowsHide: true });
    } catch (cause) {
      throw new Error('source validation requires Python 3 with stdlib lzma; XZ decode failed', { cause });
    }
  } else throw new Error('unknown compressed asset encoding');
  if (raw.length !== item.bytes || hash(raw) !== item.sha256) throw new Error('expanded asset identity mismatch');
  return raw;
}
// Generic bounded primitive is exported for tiny fixture tests. The production CLI never
// accepts a caller index or path override: its complete 44-path index is hash-pinned above.
export function preparePinnedAuthoringAssets(root, assets) {
  root = path.resolve(root); assertComponents(root);
  if (!fs.lstatSync(root).isDirectory()) throw new Error('asset root is not a directory');
  if (!Array.isArray(assets) || !assets.length || assets.length > 44) throw new Error('invalid asset census');
  const paths = new Set(), inputs = new Map(), pending = [];
  let total = 0;
  // Validate all specifications and outputs before reading compressed inputs or writing.
  for (const item of assets) {
    checkIdentity(item); checkIdentity(item.storage);
    total += item.bytes;
    if (total > 64 * 1024 * 1024) throw new Error('asset census exceeds memory bound');
    if (!['raw', 'gzip', 'xz'].includes(item.storage.encoding)) throw new Error('unknown storage encoding');
    const output = contained(root, item.path), input = contained(root, item.storage.path);
    if (paths.has(output)) throw new Error('duplicate asset output');
    paths.add(output);
    if (item.storage.encoding === 'raw' && (input !== output || item.bytes !== item.storage.bytes ||
        item.sha256 !== item.storage.sha256)) throw new Error('raw assets must already exist at original paths');
    if (item.storage.encoding !== 'raw' && input === output) throw new Error('compressed input overlaps output');
    const previous = inputs.get(input);
    const identity = JSON.stringify([item.storage.encoding, item.storage.bytes, item.storage.sha256]);
    if (previous && previous !== identity) throw new Error('conflicting storage identity');
    inputs.set(input, identity);
    assertComponents(output, true);
    if (fs.lstatSync(output, { throwIfNoEntry: false })) readPinned(output, item.bytes, item.sha256);
    else if (item.storage.encoding === 'raw') throw new Error('missing original raw asset: ' + item.path);
  }
  for (const [input] of inputs) {
    // Raw input/output equality is intentional; compressed inputs cannot overlap any output.
    const item = assets.find(a => contained(root, a.storage.path) === input);
    if (item.storage.encoding !== 'raw' && paths.has(input)) throw new Error('compressed input overlaps output census');
  }
  const decoded = new Map();
  // Every compressed object is checked and decoded, including when its output already exists.
  // In particular Python absence or malformed final XZ fails before the first output write.
  for (const item of assets) {
    if (item.storage.encoding === 'raw') continue;
    const input = contained(root, item.storage.path);
    const key = input + ':' + item.bytes + ':' + item.sha256;
    if (!decoded.has(key)) decoded.set(key, decodePinnedAsset(
      readPinned(input, item.storage.bytes, item.storage.sha256), item));
    pending.push({ item, raw: decoded.get(key) });
  }
  const results = [];
  // Publication is exclusive per file, not a cross-file transaction. On a late filesystem
  // error, previously published valid originals remain; a rerun verifies and resumes safely.
  for (const { item, raw } of pending)
    results.push(publishPinnedBytes(root, item.path, raw, item));
  return { verified: assets.length, created: results.filter(r => r.created).length };
}
export function materializeHundredHandAuthoringAssets(root) {
  root = path.resolve(root);
  const index = JSON.parse(readPinned(contained(root, INDEX_PATH), INDEX_BYTES, AUTHORING_INDEX_SHA256));
  if (index.schema !== 'spaceface-hundred-hand-authoring-assets-v1' || index.assets.length !== 44)
    throw new Error('invalid authoring index');
  return preparePinnedAuthoringAssets(root, index.assets);
}
if (import.meta.url.startsWith('file:') && process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url))
  console.log(JSON.stringify(materializeHundredHandAuthoringAssets(fileURLToPath(new URL('../../', import.meta.url)))));

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { gzipSync } from 'node:zlib';
import { preparePinnedAuthoringAssets, decodePinnedAsset, materializeHundredHandAuthoringAssets } from '../scripts/lib/materializeHundredHandAuthoringAssets.mjs';
const raw = Buffer.from('original authoring bytes\n'.repeat(8));
const hash = b => createHash('sha256').update(b).digest('hex');
const identity = b => ({ bytes: b.length, sha256: hash(b) });
const gz = gzipSync(raw);
const xz = execFileSync('python3', ['-I','-S','-c','import sys,lzma;sys.stdout.buffer.write(lzma.compress(sys.stdin.buffer.read()))'], { input: raw, maxBuffer: 1024 });
const item = (name, encoding, bytes) => ({ path: 'out/' + name, ...identity(raw),
  storage: { path: name, encoding, ...identity(bytes) } });
const a = item('a.gz','gzip',gz), b = item('b.xz','xz',xz);
function reserve() {
  const s = fs.statfsSync(os.tmpdir());
  assert(s.bavail * s.bsize >= 3072 * 1024, 'retain 3072 KiB temporary reserve');
}
function fixture(run) {
  reserve();
  const root = fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), 'hh-authoring-'));
  try {
    fs.writeFileSync(path.join(root,'a.gz'),gz);
    fs.writeFileSync(path.join(root,'b.xz'),xz);
    return run(root);
  } finally { fs.rmSync(root,{recursive:true,force:true}); reserve(); }
}
const exists = (r,p) => fs.existsSync(path.join(r,p));
test('explicit authoring preparation validates the complete input set first', async t => {
  await t.test('gzip and XZ originals materialize; repeats preserve mtimes', () => fixture(root => {
    assert.deepEqual(preparePinnedAuthoringAssets(root,[a,b]),{verified:2,created:2});
    const before=fs.statSync(path.join(root,a.path),{bigint:true}).mtimeNs;
    assert.deepEqual(fs.readFileSync(path.join(root,b.path)),raw);
    assert.equal(preparePinnedAuthoringAssets(root,[a,b]).created,0);
    assert.equal(fs.statSync(path.join(root,a.path),{bigint:true}).mtimeNs,before);
    assert.deepEqual(fs.readdirSync(path.join(root,'out')).sort(),['a.gz','b.xz']);
  }));
  await t.test('missing final input leaves first output absent', () => fixture(root => {
    fs.unlinkSync(path.join(root,'b.xz'));
    assert.throws(()=>preparePinnedAuthoringAssets(root,[a,b]),/missing/);
    assert(!exists(root,'out'));
  }));
  await t.test('bad final compressed identity leaves first output absent', () => fixture(root => {
    assert.throws(()=>preparePinnedAuthoringAssets(root,[a,{...b,storage:{...b.storage,sha256:'0'.repeat(64)}}]),/checksum/);
    assert(!exists(root,'out'));
  }));
  await t.test('bad expanded identity leaves every output absent', () => fixture(root => {
    assert.throws(()=>preparePinnedAuthoringAssets(root,[a,{...b,sha256:'0'.repeat(64)}]),/expanded/);
    assert(!exists(root,'out'));
  }));
  await t.test('Python absence fails before partial publication', () => fixture(root => {
    const old=process.env.PATH;
    process.env.PATH='';
    try { assert.throws(()=>preparePinnedAuthoringAssets(root,[a,b]),/Python 3/); }
    finally { if(old===undefined) delete process.env.PATH; else process.env.PATH=old; }
    assert(!exists(root,'out'));
  }));
  await t.test('raw entries must already exist and retain bytes', () => fixture(root => {
    const entry={path:'a.gz',...identity(gz),storage:{path:'a.gz',encoding:'raw',...identity(gz)}};
    assert.deepEqual(preparePinnedAuthoringAssets(root,[entry,b]),{verified:2,created:1});
    assert.deepEqual(fs.readFileSync(path.join(root,'a.gz')),gz);
    assert.throws(()=>preparePinnedAuthoringAssets(root,[{...entry,path:'absent',storage:{...entry.storage,path:'absent'}}]),/missing original/);
  }));
  await t.test('foreign output is not replaced', () => fixture(root => {
    fs.mkdirSync(path.join(root,'out')); fs.writeFileSync(path.join(root,b.path),'foreign');
    assert.throws(()=>preparePinnedAuthoringAssets(root,[a,b]),/byte count/);
    assert(!exists(root,a.path));
    assert.equal(fs.readFileSync(path.join(root,b.path),'utf8'),'foreign');
  }));
  await t.test('symlink input is refused', () => fixture(root => {
    fs.unlinkSync(path.join(root,'b.xz')); fs.symlinkSync('a.gz',path.join(root,'b.xz'));
    assert.throws(()=>preparePinnedAuthoringAssets(root,[a,b]),/symlink/);
    assert(!exists(root,'out'));
  }));
  await t.test('unsafe paths, overlapping census, duplicates and unknown codecs fail', () => fixture(root => {
    for(const entry of [{...a,path:'../bad'}, {...a,path:'b.xz'}, {...a,storage:{...a.storage,encoding:'zip'}}])
      assert.throws(()=>preparePinnedAuthoringAssets(root,[entry,b]));
    assert.throws(()=>preparePinnedAuthoringAssets(root,[a,a]),/duplicate/);
    assert(!exists(root,'out'));
  }));
  await t.test('XZ output limit, truncated stream and trailing bytes fail', () => {
    assert.throws(()=>decodePinnedAsset(xz,{...b,bytes:raw.length-1}),/XZ/);
    for(const bytes of [xz.subarray(0,xz.length-1),Buffer.concat([xz,Buffer.from('trailing')])])
      assert.throws(()=>decodePinnedAsset(bytes,{...b,storage:{...b.storage,...identity(bytes)}}),/XZ/);
  });
  await t.test('fixed CLI cannot accept an unpinned index', () => fixture(root => {
    assert.throws(()=>materializeHundredHandAuthoringAssets(root),/missing/);
    assert(!exists(root,'out'));
  }));
});
